// Weekly brief: an exception-based digest for a busy reader.
// Order: banner -> four numbers -> items that need a decision (full detail) -> compact watch list -> one closing line.
// Sentiment (positive / neutral / negative) and risk (ignore / watch / respond_now) are two separate labels.
// Old rows (verified / unconfirmed / possible / needs_human_review, Confidence column) are still understood.
const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const inWindow = (row) => {
  const raw = row['Date'] || row['date'];
  if (!raw) return false;
  const d = new Date(raw);
  return !isNaN(d.getTime()) && d >= sevenDaysAgo;
};
const get = (row, key) => String(row[key] || row[key.replace(/ /g, '')] || '');
const uniq = (rows) => [...new Map(rows.map(r => [get(r, 'Source URL'), r])).values()];
const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, '&#39;');
const cut = (s, n) => { const t = String(s || ''); return t.length > n ? t.slice(0, n - 1) + '\u2026' : t; };
const safeUrl = (u) => { const x = String(u || ''); const l = x.toLowerCase(); return (l.startsWith('http://') || l.startsWith('https://')) ? x : '#'; };

const logRows = $('Read Mentions Log').all().map(r => r.json).filter(inWindow);
const pendingRows = $('Read Pending Approval').all().map(r => r.json).filter(inWindow);

const status = (r) => get(r, 'Status').toLowerCase();
const sentiment = (r) => get(r, 'Sentiment').toLowerCase();
const risk = (r) => { const v = get(r, 'Risk').toLowerCase(); return v === 'needs_human_review' ? 'watch' : v; };
const rank = { respond_now: 0, watch: 1, ignore: 2 };
const byRisk = (a, b) => (rank[risk(a)] !== undefined ? rank[risk(a)] : 3) - (rank[risk(b)] !== undefined ? rank[risk(b)] : 3);
const score = (r) => { const n = parseFloat(get(r, 'Match Score') || get(r, 'Confidence')); return Number.isFinite(n) ? n.toFixed(2) : ''; };

const failed = logRows.filter(r => status(r) === 'failed' || get(r, 'Risk').toLowerCase() === 'error');
const discarded = uniq(logRows.filter(r => status(r) === 'discarded'));
const kept = uniq(logRows.filter(r => status(r).startsWith('logged')));
const review = kept.filter(r => status(r).includes('needs your review') || status(r).includes('unconfirmed') || status(r).includes('possible')).sort(byRisk);
const mentions = kept.filter(r => !review.includes(r)).sort(byRisk);
const drafts = uniq(pendingRows.filter(r => status(r) === 'pending_approval'));
const draftLinks = new Set(drafts.map(r => get(r, 'Source URL')));

const urgentNoDraft = mentions.filter(r => risk(r) === 'respond_now' && !draftLinks.has(get(r, 'Source URL')));
const urgentReview = review.filter(r => risk(r) === 'respond_now');
const glance = mentions.filter(r => risk(r) === 'watch');
const rest = mentions.filter(r => risk(r) !== 'watch' && risk(r) !== 'respond_now');
const negative = kept.filter(r => sentiment(r) === 'negative').length;

const dateStr = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

// ---------- Verdict ----------
const alerts = [];
if (drafts.length) alerts.push(plural(drafts.length, 'draft') + ' waiting for your approval');
if (urgentNoDraft.length) alerts.push(plural(urgentNoDraft.length, 'urgent mention') + ' with no draft');
if (urgentReview.length) alerts.push(plural(urgentReview.length, 'urgent mention') + ' to review');
let headline, bannerColor;
if (alerts.length) { headline = alerts.join(' \u00b7 '); bannerColor = '#B91C1C'; }
else if (glance.length + review.length > 0) { headline = plural(glance.length + review.length, 'mention') + ' worth a look, nothing urgent'; bannerColor = '#B45309'; }
else if (kept.length === 0) { headline = 'No new mentions this week'; bannerColor = '#4B5563'; }
else { headline = 'All clear, nothing needs your attention'; bannerColor = '#15803D'; }

const closing = [];
if (rest.length) closing.push(plural(rest.length, 'other mention') + ' needed no action.');
if (discarded.length) closing.push(plural(discarded.length, 'search result') + ' dismissed as unrelated or harmless.');
const closingText = closing.join(' ');

// ---------- Plain-text version ----------
const t = [
  'Reputation Radar \u2014 Weekly Brief (' + dateStr + ')',
  '',
  headline.toUpperCase(),
  'Total mentions ' + kept.length + ' | Negative ' + negative + ' | Needs your review ' + review.length + ' | Pending approval ' + drafts.length,
  ''
];
if (failed.length) { t.push('WARNING: ' + plural(failed.length, 'search failure') + ' this week, check the Mentions Log.'); t.push(''); }
if (drafts.length || urgentNoDraft.length) {
  t.push('NEEDS YOUR APPROVAL');
  for (const r of drafts) {
    t.push('- ' + get(r, 'Title'));
    t.push('  ' + get(r, 'Source URL'));
    t.push('  [' + (sentiment(r) || 'n/a') + ' | risk: ' + risk(r) + ']');
    t.push('  Draft: ' + get(r, 'Draft Response'));
  }
  for (const r of urgentNoDraft) {
    t.push('- ' + get(r, 'Title') + ' (urgent, no draft was created)');
    t.push('  ' + get(r, 'Source URL'));
    t.push('  [' + (sentiment(r) || 'n/a') + ' | risk: ' + risk(r) + '] ' + get(r, 'Reasoning'));
  }
  t.push('');
}
if (review.length) {
  t.push('NEEDS YOUR REVIEW (could not verify these are about Nidhi / Growpido, but a crisis keyword appeared)');
  for (const r of review) {
    t.push('- [' + (sentiment(r) || 'n/a') + ' | risk: ' + risk(r) + '] ' + get(r, 'Title') + (score(r) ? ' | match ' + score(r) : ''));
    t.push('  ' + get(r, 'Source URL'));
    if (get(r, 'Reasoning')) t.push('  ' + get(r, 'Reasoning'));
  }
  t.push('');
}
if (glance.length) {
  t.push('WORTH A GLANCE');
  for (const r of glance) {
    t.push('- [' + (sentiment(r) || 'n/a') + '] ' + get(r, 'Title'));
    t.push('  ' + get(r, 'Source URL'));
  }
  t.push('');
}
if (closingText) { t.push(closingText); t.push(''); }
t.push('Nothing was posted automatically. Drafts are held until you approve them.');
t.push('- Reputation Radar (Growpido)');

// ---------- HTML version ----------
const chip = (label, fg, bg) => `<span style='display:inline-block;padding:2px 8px;margin-right:4px;border-radius:10px;font-size:11px;font-weight:700;letter-spacing:.03em;text-transform:uppercase;background:${bg};color:${fg};'>${esc(label)}</span>`;
const RISK = { respond_now: ['#B91C1C', '#FEE2E2'], watch: ['#B45309', '#FEF3C7'], ignore: ['#166534', '#DCFCE7'] };
const SENT = { negative: ['#B91C1C', '#FEE2E2'], neutral: ['#4B5563', '#F3F4F6'], positive: ['#166534', '#DCFCE7'] };
const riskChip = (r) => { const c = RISK[risk(r)] || ['#4B5563', '#F3F4F6']; return chip(risk(r).replace('_', ' '), c[0], c[1]); };
const sentChip = (r) => { const s = sentiment(r); if (!s) return ''; const c = SENT[s] || ['#4B5563', '#F3F4F6']; return chip(s, c[0], c[1]); };
const F = 'font-family:Arial,Helvetica,sans-serif;';
const link = (r) => `<a href='${esc(safeUrl(get(r, 'Source URL')))}' style='font-size:14px;font-weight:700;color:#111827;text-decoration:none;'>${esc(get(r, 'Title') || get(r, 'Source URL'))}</a>`;

const header = (title, sub) => `<tr><td style='padding:20px 20px 6px 20px;${F}'><div style='font-size:13px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.04em;'>${esc(title)}</div><div style='font-size:12px;color:#6B7280;margin-top:2px;'>${esc(sub)}</div></td></tr>`;

const detailRow = (r, o) => `<tr><td style='padding:12px 20px;border-bottom:1px solid #E5E7EB;${F}${o.bg ? 'background:' + o.bg + ';' : ''}'><div style='margin-bottom:5px;'>${riskChip(r)}${sentChip(r)}${o.score && score(r) ? chip('match ' + score(r), '#4B5563', '#F3F4F6') : ''}${o.tag ? chip(o.tag, '#B91C1C', '#FEE2E2') : ''}</div>${link(r)}${get(r, 'Reasoning') ? `<div style='font-size:13px;color:#6B7280;margin-top:3px;'>${esc(cut(get(r, 'Reasoning'), 220))}</div>` : ''}</td></tr>`;

const draftRow = (r) => `<tr><td style='padding:14px 20px;border-bottom:1px solid #E5E7EB;background:#FEF2F2;${F}'><div style='margin-bottom:5px;'>${riskChip(r)}${sentChip(r)}</div>${link(r)}<div style='margin-top:8px;padding:10px 12px;background:#ffffff;border:1px solid #E5E7EB;border-radius:6px;font-size:13px;color:#374151;white-space:pre-wrap;'>${esc(get(r, 'Draft Response'))}</div></td></tr>`;

const glanceRow = (r) => `<tr><td style='padding:9px 20px;border-bottom:1px solid #F3F4F6;${F}'>${sentChip(r)}${link(r)}${get(r, 'Reasoning') ? `<div style='font-size:12px;color:#6B7280;margin-top:2px;'>${esc(cut(get(r, 'Reasoning'), 110))}</div>` : ''}</td></tr>`;

const stat = (n, label) => `<td align='center' style='padding:12px 4px;${F}'><div style='font-size:22px;font-weight:700;color:#111827;'>${n}</div><div style='font-size:11px;color:#6B7280;text-transform:uppercase;letter-spacing:.03em;'>${esc(label)}</div></td>`;

let rows = '';
if (failed.length) rows += `<tr><td style='padding:10px 20px;background:#FFFBEB;border-bottom:1px solid #FDE68A;${F}font-size:13px;color:#92400E;'>Warning: ${esc(plural(failed.length, 'search failure'))} this week, check the Mentions Log.</td></tr>`;
if (drafts.length || urgentNoDraft.length) {
  rows += header('Needs your approval', 'Drafts are held. Nothing is sent until you approve it.');
  rows += drafts.map(draftRow).join('');
  rows += urgentNoDraft.map(r => detailRow(r, { tag: 'no draft created', bg: '#FEF2F2' })).join('');
}
if (review.length) {
  rows += header('Needs your review', 'Could not verify these are about Nidhi or Growpido, but a crisis keyword appeared. Check if it is really her.');
  rows += review.map(r => detailRow(r, { score: true })).join('');
}
if (glance.length) {
  rows += header('Worth a glance', 'Content that is unclear or borderline.');
  rows += glance.map(glanceRow).join('');
}
if (closingText) rows += `<tr><td style='padding:16px 20px;${F}font-size:13px;color:#6B7280;'>${esc(closingText)}</td></tr>`;

const html = `<!DOCTYPE html><html><body style='margin:0;padding:24px 0;background:#F3F4F6;'>
<table role='presentation' width='100%' cellpadding='0' cellspacing='0'><tr><td align='center' style='padding:0 8px;'>
<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='max-width:600px;background:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #E5E7EB;'>
<tr><td style='padding:22px 20px 14px 20px;${F}'><div style='font-size:12px;color:#9CA3AF;text-transform:uppercase;letter-spacing:.05em;font-weight:700;'>Growpido</div><div style='font-size:20px;font-weight:700;color:#111827;margin-top:2px;'>Reputation Radar</div><div style='font-size:13px;color:#6B7280;'>Weekly Brief &middot; ${esc(dateStr)}</div></td></tr>
<tr><td style='padding:14px 20px;background:${bannerColor};${F}font-size:15px;font-weight:700;color:#ffffff;'>${esc(headline)}</td></tr>
<tr><td style='padding:4px 8px;border-bottom:1px solid #E5E7EB;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0'><tr>${stat(kept.length, 'Total mentions')}${stat(negative, 'Negative')}${stat(review.length, 'Needs your review')}${stat(drafts.length, 'Pending approval')}</tr></table></td></tr>
${rows}
<tr><td style='padding:16px 20px;border-top:1px solid #E5E7EB;${F}font-size:12px;color:#9CA3AF;'>Nothing was posted automatically. Drafts are held until you approve them.<br/>Reputation Radar &middot; Growpido</td></tr>
</table></td></tr></table>
</body></html>`;

return [{
  subject: (alerts.length ? 'Action needed: ' : '') + 'Reputation Radar \u2014 Weekly Brief (' + dateStr + ')',
  body: t.join('\n'),
  html
}];
